// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  var custom_fields = item.json.custom_fields;
  for (const cf of custom_fields) {
    if (cf.name.toLowerCase().includes("status")) {
      item.json.status = cf.display_value;
    }
  }
}

return $input.all();

const rocks = $('Code in JavaScript').all();
const allMilestones = $('Get many subtasks').all();

let projectSummary = "";

rocks.forEach(rock => {
  const rockGid = rock.json.gid;
  // Filter milestones belonging to this specific rock
  const milestones = allMilestones.filter(m => m.json.parent.gid === rockGid);

  const completed = milestones.filter(m => m.json.completed).length;
  const total = milestones.length;
  const stagnant = milestones.filter(m => {
    if (m.json.completed) return false;
    const daysSince = (new Date() - new Date(m.json.modified_at)) / (1000 * 60 * 60 * 24);
    return daysSince > 7;
  });

  projectSummary += `\nROCK: ${rock.json.name} [Status: ${rock.json.health_status}]\n`;
  projectSummary += `Progress: ${completed}/${total} milestones done.\n`;

  if (stagnant.length > 0) {
    projectSummary += `⚠️ STAGNANT MILESTONES:\n` + stagnant.map(s => `- ${s.json.name} (Last updated: ${s.json.modified_at})`).join('\n') + '\n';
  }
});

return { summary_context: projectSummary };

