// 1. Extract the JSON from the OpenAI response
// The path matches your provided JSON: $json.output[0].content[0].text
const aiOutput = $json.output[0].content[0].text;

// 2. Helper function to escape newlines for Slack Block Kit
const clean = (str) => {
  if (typeof str !== 'string') return str || "";
  return str.replace(/\n/g, "\\n").replace(/\r/g, "\\n");
};

// 3. Pre-format the arrays into Markdown strings
const formatList = (arr, templateFn) => {
  if (!Array.isArray(arr) || arr.length === 0) return "_No items reported._";
  return arr.map(templateFn).join('\\n');
};

return {
  // Map 'summary_of_actions_taken' to the headline field
  headline: clean(aiOutput.summary_of_actions_taken),

  // Map 'overall_rock_health' to the health field
  health: clean(aiOutput.overall_rock_health),

  // Format the 'advanced_rocks' array
  updated_list: clean(formatList(aiOutput.advanced_rocks, 
    item => `• *${item.rock_name}*: ${item.progress_made}`)),

  // Format the 'rocks_requiring_action' array
  stagnant_list: clean(formatList(aiOutput.rocks_requiring_action, 
    item => `• *${item.rock_name}*: ${item.reason}`)),

  // Format the 'leadership_recommendations' array
  actions_list: clean(formatList(aiOutput.leadership_recommendations, 
    action => `• ${action}`))
};

// This node runs when a Rock has ZERO subtasks
const rocks = $('Code in JavaScript').all();
const projectGid = $('Project Return').first().json.gid;

let projectSummary = `PROJECT GID: ${projectGid}\n`;

rocks.forEach(rock => {
  const rockGid = rock.json.gid;

  projectSummary += `\nROCK: ${rock.json.name} [GID: ${rockGid}] [Status: ${rock.json.health_status}]\n`;
  projectSummary += `⚠️ SYSTEM ALERT: No milestones/subtasks found for this Rock.\n`;
  projectSummary += `Note: Accountability cannot be tracked because no specific tasks are defined.\n`;
});

return { 
  summary_context: projectSummary.trim(),
  no_milestones_flag: true 
};

// 1. Extract the JSON from the "No-Milestone" OpenAI response
const aiOutput = $json.output[0].content[0].text;

// 2. Helper function to escape newlines for Slack Block Kit
const clean = (str) => {
  if (typeof str !== 'string') return str || "";
  return str.replace(/\n/g, "\\n").replace(/\r/g, "\\n");
};

// 3. Pre-format the arrays into Markdown strings
// Special handling for the empty 'advanced_rocks' array
const formatList = (arr, templateFn) => {
  if (!Array.isArray(arr) || arr.length === 0) return "_No Rocks have advanced (Missing Milestones)_";
  return arr.map(templateFn).join('\\n');
};

return {
  // Map the new keys to your standard Slack Block variables
  headline: clean(aiOutput.summary_of_actions_taken),
  health: clean(aiOutput.overall_rock_health),

  // Format the 'advanced_rocks' (likely empty in this branch)
  updated_list: clean(formatList(aiOutput.advanced_rocks, 
    item => `• *${item.rock_name}*: ${item.progress_made}`)),

  // Format the 'rocks_requiring_action' (the primary focus here)
  stagnant_list: clean(formatList(aiOutput.rocks_requiring_action, 
    item => `• *${item.rock_name}*: ${item.reason}`)),

  // Format the 'leadership_recommendations'
  actions_list: clean(formatList(aiOutput.leadership_recommendations, 
    action => `• ${action}`))
};

